<?php
$adminUrl=is_callable($adminUrl??null)?$adminUrl:static fn(string $path=''):string=>'/'.trim($path,'/');$noticeMessages=['reviewed'=>'Submission marked reviewed.'];$notice=is_scalar($notice??null)?($noticeMessages[(string)$notice]??null):null;$error=is_scalar($error??null)?(string)$error:'';
?>
<section class="admin-content-form-page" aria-labelledby="submission-detail-title"><header class="admin-content-form-header"><div><p class="admin-content-eyebrow">Form Manager</p><h2 id="submission-detail-title">Submission details</h2><p>Historical values are retained independently of later form-definition edits.</p></div><a class="admin-button admin-button--secondary" href="<?=htmlspecialchars($adminUrl('forms/submissions'),ENT_QUOTES,'UTF-8')?>">Back to submissions</a></header><div class="admin-panel"><div class="admin-content-form-card"><?php if($notice):?><div class="admin-alert admin-alert--success" role="status"><?=htmlspecialchars($notice,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error!==''):?><div class="admin-alert admin-alert--danger" role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="form-manager-submission-summary" aria-labelledby="submission-summary-title"><h3 id="submission-summary-title">Submission</h3><dl><dt>Form</dt><dd><?=htmlspecialchars($form->name(),ENT_QUOTES,'UTF-8')?></dd><dt>Status</dt><dd><?=htmlspecialchars(ucfirst($submission->status()),ENT_QUOTES,'UTF-8')?></dd><dt>Received</dt><dd><?=htmlspecialchars($submission->createdAt(),ENT_QUOTES,'UTF-8')?></dd><dt>Updated</dt><dd><?=htmlspecialchars($submission->updatedAt(),ENT_QUOTES,'UTF-8')?></dd></dl></section><section aria-labelledby="submission-values-title"><h3 id="submission-values-title">Retained values</h3><?php foreach($submission->values() as $value):?><dl class="form-manager-submission-value"><dt><?=htmlspecialchars($value->fieldLabel(),ENT_QUOTES,'UTF-8')?></dt><dd><?=htmlspecialchars($value->valueLabel()??$value->valueText(),ENT_QUOTES,'UTF-8')?></dd><dt>Field key</dt><dd><code><?=htmlspecialchars($value->fieldKey(),ENT_QUOTES,'UTF-8')?></code></dd><dt>Field type</dt><dd><?=htmlspecialchars($value->fieldType(),ENT_QUOTES,'UTF-8')?></dd><?php if($value->valueLabel()!==null):?><dt>Stored value</dt><dd><?=htmlspecialchars($value->valueText(),ENT_QUOTES,'UTF-8')?></dd><?php endif;?><?php if($value->fieldId()===null):?><dt>Provenance</dt><dd>Current field definition is unavailable; retained snapshot shown.</dd><?php endif;?></dl><?php endforeach;?></section><div class="admin-actions"><?php if($submission->status()==='new'):?><form method="post" action="<?=htmlspecialchars($adminUrl('forms/submissions/'.$submission->id()->value().'/review'),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="_token" value="<?=htmlspecialchars((string)($csrfToken??''),ENT_QUOTES,'UTF-8')?>"><button class="admin-button admin-button--primary" type="submit">Mark submission reviewed</button></form><?php endif;?><?php if(!empty($canDelete)):?><form method="post" action="<?=htmlspecialchars($adminUrl('forms/submissions/'.$submission->id()->value().'/delete'),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="_token" value="<?=htmlspecialchars((string)($csrfToken??''),ENT_QUOTES,'UTF-8')?>"><button class="admin-button admin-button--link" type="submit">Delete submission permanently</button></form><?php endif;?></div></div></div></section>
